```go
package main

import "fmt"

func main() {
	left := make(chan string, 1)
	right := make(chan string, 1)
	left <- "left"
	right <- "right"

	var first string
	select {
	case first = <-left:
	case first = <-right:
	}

	if first != "left" && first != "right" {
		panic("unexpected selection")
	}
	fmt.Println(first)
}
```
Both receives are ready before select. Either printed value is correct; source order does not make left the priority.

```go
package main

import "fmt"

func trySend(ch chan<- int, value int) bool {
	select {
	case ch <- value:
		return true
	default:
		return false
	}
}

func main() {
	queue := make(chan int, 1)
	first := trySend(queue, 10)
	second := trySend(queue, 20)
	if !first || second {
		panic("unexpected queue result")
	}
	fmt.Println(first, second, <-queue)
}
```
The second call reports immediate backpressure. The caller receives a fact it can act on instead of silently spinning.
